def net_quantities(events):
    seen = {}
    totals = {}
    for event in events:
        eid = event["event_id"]
        payload = (event["sku"], event["delta"])
        if eid in seen:
            if seen[eid] != payload:
                raise ValueError("Conflicting event payload")
            continue
        seen[eid] = payload
        sku, delta = payload
        totals[sku] = totals.get(sku, 0) + delta
    return totals

